//! SHARC machine that runs the decoded B3 Bass generator `0x121BBE` and processor `0x122296`.
//!
//! Research: `docs/research/organ-farfisa-bass.md` s15. The two routines are not re-derived: the
//! listings are decoded by `tools/sharc_listing_rust.py` into integer rows (`prog_gen.rs`,
//! `prog_proc.rs`, GENERATED by `tools/organ_bass_fw_gen.py`) and executed here with the rules the
//! Python interpreter proved bit exact against `sharc-chain` over thousands of calls
//! (`f40.rs`, `exec.rs`). The scanner phase, the lattice sections, the delay taps and the 40 bit
//! float behaviour are therefore the firmware's own.
//!
//! Real-time safety: construction allocates the DM image; `call` and `run` do not allocate, lock or
//! perform I/O.

mod compile;
mod exec;
mod f40;
mod fast;
mod fastexec;
mod native_bass_gen;
mod native_bass_proc;
#[cfg(test)]
pub(super) mod native_gen;
mod plan;
#[cfg(test)]
mod probe;
mod prog_gen;
mod prog_proc;
pub(in crate::organ) mod tables;

use compile::Program;
use tables::kind;

pub(super) use prog_gen::GEN_ROWS;
pub(super) use prog_proc::PROC_ROWS;

/// One decoded row (`tools/sharc_listing_rust.py`).
pub(super) type Row = [i32; 8];

/// DM window of the machine: one flat array from `DM_BASE` (VERIFIED: the words the Bass routines
/// address are weights and tables `0x95000`, state and delay line `0xB3000`, the output stream
/// `0xC0000`, cabinet and scanner words `0xC2B00`; the Farfisa processor adds `0xC27E0..0xC2E00` and
/// `0xC4000`, research s13 / s16). A flat window is one bounds check per access; anything outside
/// reads 0 and is dropped.
pub(super) const DM_BASE: u32 = 0x9_5000;
pub(super) const DM_LEN: usize = 0x3_0000;

/// Output stream words of the processor (`DM 0xC00EA`, four words per call).
pub(super) const OUT_BASE: u32 = 0xC_00EA;
/// Presets of the generator and processor calls (`I0`, `I1`; VERIFIED, as the oracle harness).
pub(super) const GEN_PRESET: (u32, u32) = (0xC_00F2, 0xB_52C7);
pub(super) const PROC_PRESET: (u32, u32) = (0xC_00EA, 0xB_472C);

/// Register file, DM and the multiplier state of the two PEs.
#[derive(Debug, Clone)]
pub(super) struct Machine {
    /// `r0..r15` (0..16) and `s0..s15` (16..32), 40 bit floats (`word << 8 | extension`).
    pub(super) d: [u64; 32],
    pub(super) i: [u32; 16],
    pub(super) m: [u32; 16],
    pub(super) l: [u32; 16],
    pub(super) b: [u32; 16],
    pub(super) lcntr: u32,
    pub(super) mr: [i128; 2],
    pub(super) an: [bool; 2],
    pub(super) az: [bool; 2],
    pub(super) mem: Box<[u32; DM_LEN]>,
    /// Temp slots of the split items (`compile.rs`): 2 slots of 4 words.
    pub(super) tmp: [u64; 8],
    /// Compiled routines (`compile.rs`): the generator (Bass only) and the processor.
    gen: Program,
    main: Program,
    /// Straight line versions of the routines (`native_*.rs`), when selected.
    gen_fn: Option<Routine>,
    main_fn: Option<Routine>,
}

/// A generated straight line routine.
pub(super) type Routine = fn(&mut Machine);

impl Machine {
    /// Zeroed machine (allocates the DM ranges; setup time only).
    pub(super) fn new() -> Self {
        Self {
            d: [0; 32],
            i: [0; 16],
            m: [0; 16],
            l: [0; 16],
            b: [0; 16],
            lcntr: 0,
            mr: [0; 2],
            an: [false; 2],
            az: [false; 2],
            mem: vec![0; DM_LEN]
                .into_boxed_slice()
                .try_into()
                .expect("DM_LEN words"),
            tmp: [0; 8],
            gen: Program::default(),
            main: Program::default(),
            gen_fn: None,
            main_fn: None,
        }
    }

    /// DM read (outside the window reads 0).
    #[inline(always)]
    pub(super) fn rd(&self, a: u32) -> u32 {
        self.mem
            .get(a.wrapping_sub(DM_BASE) as usize)
            .copied()
            .unwrap_or(0)
    }

    /// DM write (outside the window is dropped).
    #[inline(always)]
    pub(super) fn wr(&mut self, a: u32, v: u32) {
        if let Some(w) = self.mem.get_mut(a.wrapping_sub(DM_BASE) as usize) {
            *w = v;
        }
    }

    /// Float word at `a`.
    pub(super) fn rd_f(&self, a: u32) -> f32 {
        f32::from_bits(self.rd(a))
    }

    /// Writes a float word.
    pub(super) fn wr_f(&mut self, a: u32, v: f32) {
        self.wr(a, v.to_bits());
    }

    /// Runs decoded rows (instructions and loops) on the reference executor.
    #[cfg(test)]
    pub(super) fn run(&mut self, rows: &[Row]) {
        let mut pd = exec::Pending::default();
        self.run_with(rows, 0, &mut pd);
    }

    /// `start` is the absolute row index of `rows[0]` (jump targets are absolute).
    #[cfg(test)]
    fn run_with(&mut self, rows: &[Row], start: usize, pd: &mut exec::Pending) {
        let mut p = 0;
        while p < rows.len() {
            let row = &rows[p];
            let n = row[if row[0] == kind::INS { 1 } else { 2 }] as usize;
            let body = &rows[p + 1..p + 1 + n];
            if row[0] == kind::INS {
                if row[3] != 0 {
                    // jump: 1 always, 2 `if ne` (AZ clear), 3 `if eq`; PEx flags, no delay slots
                    let taken = row[3] == 1 || (row[3] == 2) != self.az[0];
                    p = if taken {
                        row[4] as usize - start
                    } else {
                        p + 1
                    };
                    continue;
                }
                self.exec(body, row[2] != 0, pd);
            } else {
                for _ in 0..row[1] {
                    self.run_with(body, start + p + 1, pd);
                }
                self.lcntr = 0;
            }
            p += 1 + n;
        }
    }

    /// Compiles the processor (`main`) and optionally the generator (setup time: allocates).
    pub(super) fn set_programs(&mut self, gen: Option<&[Row]>, main: &[Row]) {
        self.gen = gen.map(compile::compile).unwrap_or_default();
        self.main = compile::compile(main);
    }

    /// Runs the generated straight line routines instead of the compiled programs (Bass).
    pub(super) fn use_native_bass(&mut self) {
        self.gen_fn = Some(native_bass_gen::gen_call);
        self.main_fn = Some(native_bass_proc::proc_call);
    }

    /// One call of the processor with the `preset`.
    pub(super) fn call_main(&mut self, preset: (u32, u32)) {
        if let Some(routine) = self.main_fn {
            self.i[0] = preset.0;
            self.i[1] = preset.1;
            return routine(self);
        }
        let prog = std::mem::take(&mut self.main);
        self.call_compiled(&prog, preset);
        self.main = prog;
    }

    #[cfg(test)]
    /// One routine call (reference executor) with the `I0` / `I1` presets of the harness.
    pub(super) fn call(&mut self, rows: &[Row], preset: (u32, u32)) {
        self.i[0] = preset.0;
        self.i[1] = preset.1;
        self.run(rows);
    }

    /// One generator + processor call (two frames) on the compiled programs; returns the two
    /// output samples. Needs [`Self::set_programs`] with both routines.
    pub(super) fn step(&mut self) -> [f32; 2] {
        if let Some(routine) = self.gen_fn {
            self.i[0] = GEN_PRESET.0;
            self.i[1] = GEN_PRESET.1;
            routine(self);
        } else {
            let gen = std::mem::take(&mut self.gen);
            self.call_compiled(&gen, GEN_PRESET);
            self.gen = gen;
        }
        self.call_main(PROC_PRESET);
        [self.rd_f(OUT_BASE), self.rd_f(OUT_BASE + 2)]
    }

    /// Loads a derived image (`docs/research/data/bass-fw-image.csv`): `R,name,hex` register rows
    /// (`r0`..`s15`, `iN`, `mN`) and `M,addr,hex hex ...` runs of DM words.
    pub(super) fn load_image(&mut self, csv: &str) {
        for line in csv.lines() {
            let f: Vec<&str> = line.split(',').collect();
            match f.as_slice() {
                ["R", name, v] => {
                    let v = u32::from_str_radix(v, 16).unwrap_or(0);
                    let n: usize = name[1..].parse().unwrap_or(0);
                    match &name[..1] {
                        "r" => self.d[n] = u64::from(v) << 8,
                        "s" => self.d[16 + n] = u64::from(v) << 8,
                        "i" => self.i[n] = v,
                        _ => self.m[n] = v,
                    }
                }
                ["M", addr, words] => {
                    let base = u32::from_str_radix(addr, 16).unwrap_or(0);
                    for (k, w) in words.split(' ').enumerate() {
                        self.wr(base + k as u32, u32::from_str_radix(w, 16).unwrap_or(0));
                    }
                }
                _ => {}
            }
        }
    }
}

/// `true` when every `INS` / `LOOP` row of `rows` is followed by its full body (generated tables).
pub(in crate::organ) fn rows_valid(rows: &[Row]) -> bool {
    let mut p = 0;
    while p < rows.len() {
        let (k, n) = (
            rows[p][0],
            rows[p][if rows[p][0] == kind::INS { 1 } else { 2 }],
        );
        if (k != kind::INS && k != kind::LOOP) || n < 0 || p + 1 + n as usize > rows.len() {
            return false;
        }
        if k == kind::LOOP && !rows_valid(&rows[p + 1..p + 1 + n as usize]) {
            return false;
        }
        p += 1 + n as usize;
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rows(items: &[Row]) -> Vec<Row> {
        let mut out = vec![[kind::INS, items.len() as i32, 0, 0, 0, 0, 0, 0]];
        out.extend_from_slice(items);
        out
    }

    #[test]
    fn memory_ranges_read_zero_outside_and_round_trip_inside() {
        let mut m = Machine::new();
        m.wr(0xB_33BA, 7);
        m.wr(0x1234, 9);
        assert_eq!(m.rd(0xB_33BA), 7);
        assert_eq!(m.rd(0x1234), 0);
        assert_eq!(m.rd(0xC_2BFF), 0);
        m.wr_f(0xC_00EA, 0.5);
        assert_eq!(m.rd_f(0xC_00EA), 0.5);
    }

    #[test]
    fn an_instruction_reads_old_state_and_writes_together() {
        // `r0<->s0`-style swap and a copy in one instruction: both read the old values.
        let mut m = Machine::new();
        m.d[0] = 0x1100;
        m.d[1] = 0x2200;
        let swap = [kind::SWAP, 0, 1, 0, 0, 0, 0, 0];
        m.run(&rows(&[swap]));
        assert_eq!((m.d[0], m.d[1]), (0x2200, 0x1100));
    }

    #[test]
    fn loops_repeat_their_body_and_clear_lcntr() {
        let mut m = Machine::new();
        // i3 = i3 + 4 (modify by immediate), three times
        let modify = [kind::MODIFY, 32 + 3, 3, 0, 4, 0, 0, 0];
        let mut prog = vec![[kind::LOOP, 3, 2, 0, 0, 0, 0, 0]];
        prog.extend(rows(&[modify]));
        m.run(&prog);
        assert_eq!(m.i[3], 12);
        assert_eq!(m.lcntr, 0);
    }

    /// Machine in the state of the oracle chord `60 64 67` (image + key-down delta).
    fn chord_machine() -> Machine {
        let mut m = Machine::new();
        m.load_image(include_str!(
            "../../../../../docs/research/data/bass-fw-image.csv"
        ));
        m.load_image(include_str!(
            "../../../../../docs/research/data/bass-fw-chord-delta.csv"
        ));
        m.set_programs(Some(&GEN_ROWS), &PROC_ROWS);
        m
    }

    #[test]
    fn decoded_chain_is_bit_exact_against_the_oracle_golden() {
        // `bass-fw-chord-golden.csv`: the output words of 48 calls of `sharc-chain` (generator
        // `0x121BBE` + processor `0x122296`, boot + model 5 install + key-down 60 64 67). VERIFIED:
        // every word equal, i.e. the 40 bit float rules, the SIMD data access, the circular buffers
        // and the scanner state of the decoded rows are the firmware's.
        let golden = include_str!("../../../../../docs/research/data/bass-fw-chord-golden.csv");
        let mut m = chord_machine();
        let mut seen = 0;
        for line in golden.lines().filter(|l| !l.starts_with('#')) {
            let f: Vec<&str> = line.split(',').collect();
            let want = [
                u32::from_str_radix(f[1], 16).unwrap(),
                u32::from_str_radix(f[2], 16).unwrap(),
            ];
            let got = m.step();
            assert_eq!([got[0].to_bits(), got[1].to_bits()], want, "call {}", f[0]);
            seen += 1;
        }
        assert_eq!(seen, 48);
    }

    #[test]
    fn image_loader_reads_registers_and_word_runs() {
        let mut m = Machine::new();
        m.load_image("R,r3,3f800000\nR,i1,b472c\nM,b33ba,10 20 30\n");
        assert_eq!(m.d[3], 0x3F80_0000u64 << 8);
        assert_eq!(m.i[1], 0xB_472C);
        assert_eq!((m.rd(0xB_33BA), m.rd(0xB_33BC)), (0x10, 0x30));
    }
}
